namespace BW\Noor;
defined('ABSPATH')||exit;
function field($key,$fallback=''){return function_exists('get_field')?(get_field($key,'option')?:$fallback):$fallback;}
function link($path){return esc_url(home_url('/'.trim($path,'/').'/'));}
function asset($file){return esc_url(get_theme_file_uri('assets/'.$file));}
function logo(){return '<span class="noor-wordmark">atelier <strong>noor</strong><i aria-hidden="true">✳</i></span>';}
function icon($name){$paths=['bag'=>'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>','user'=>'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>','search'=>'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>'];return '<svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true">'.($paths[$name]??'').'</svg>';}
function header(){ob_start();?><a class="skip-link" href="#inhoud">Ga naar de inhoud</a><div class="noor-topbar">Bijzondere vondsten voor thuis <span>•</span> Gratis verzending vanaf € 75 in België</div><div class="noor-header"><button class="noor-menu-toggle" aria-expanded="false" aria-controls="noor-menu">Menu <span aria-hidden="true">☰</span></button><nav id="noor-menu" aria-label="Hoofdnavigatie"><a href="<?=link('winkel')?>">De collectie</a><a href="<?=link('ons-verhaal')?>">Ons verhaal</a><a href="<?=link('inspiratie')?>">Inspiratie</a><a href="<?=link('contact')?>">Contact</a></nav><a class="noor-logo" href="<?=link('')?>" aria-label="Atelier Noor — homepage"><?=logo()?></a><div class="noor-header-actions"><a href="<?=link('zoeken')?>" aria-label="Zoek producten"><?=icon('search')?></a><a href="<?=link('mijn-account')?>" aria-label="Mijn account"><?=icon('user')?></a><a class="noor-cart" href="<?=link('winkelmand')?>" aria-label="Winkelmand"><?=icon('bag')?><span class="noor-cart-count"><?=function_exists('WC')&&WC()->cart?WC()->cart->get_cart_contents_count():0?></span></a></div></div><?php return ob_get_clean();}
function hero(){ $slides=(array)field('noor_hero_slides',[]); if(!$slides)return '';ob_start();?><section class="noor-hero" aria-roledescription="carrousel" aria-label="Uitgelichte collectie"><div class="noor-slides"><?php foreach($slides as$i=>$s):$id=(int)($s['product']??0);$pr=function_exists('wc_get_product')?wc_get_product($id):null;?><article class="noor-slide <?=$i===0?'is-active':''?>" <?=$i?'hidden':''?> aria-label="<?=($i+1).' van '.count($slides)?>"><img class="noor-hero-image" src="<?=esc_url(wp_get_attachment_image_url($s['image'],'full'))?>" alt="<?=esc_attr(get_post_meta($s['image'],'_wp_attachment_image_alt',true))?>" <?=$i?'loading="lazy"':'fetchpriority="high"'?>><div class="noor-hero-copy"><p class="noor-eyebrow"><?=esc_html($s['label'])?></p><?php $heading=$i===0?'h1':'h2';echo "<".$heading.">".esc_html($s['title'])."</".$heading.">";?><a class="noor-textlink" href="<?=esc_url($id?get_permalink($id):home_url('/winkel/'))?>"><?=esc_html($s['button']?:'Ontdek de collectie')?> <span aria-hidden="true">↗</span></a></div><?php if($pr):?><a class="noor-hero-product" href="<?=esc_url(get_permalink($id))?>"><?=$pr->get_image('woocommerce_thumbnail')?><span><?=esc_html($pr->get_name())?><small><?=$pr->get_price_html()?></small></span><span class="noor-product-plus" aria-hidden="true">+</span></a><?php endif;?></article><?php endforeach;?></div><div class="noor-slide-controls"><button class="noor-prev" aria-label="Vorige slide">←</button><span class="noor-slide-number" aria-live="polite">01</span><span class="noor-slide-rule"></span><span><?=str_pad(count($slides),2,'0',STR_PAD_LEFT)?></span><button class="noor-next" aria-label="Volgende slide">→</button></div></section><?php return ob_get_clean();}
function products(){return '<div class="noor-product-section">'.do_shortcode('[products limit="4" columns="4" visibility="featured" orderby="menu_order" order="ASC"]').'</div>';}
function categories(){ob_start();?><div class="noor-categories"><?php $terms=get_terms(['taxonomy'=>'product_cat','hide_empty'=>true,'exclude'=>[get_option('default_product_cat')]]);foreach($terms as$i=>$t):$img=get_term_meta($t->term_id,'thumbnail_id',true);?><a class="noor-category noor-reveal" href="<?=esc_url(get_term_link($t))?>"><div><?=wp_get_attachment_image($img,'large')?></div><span><span class="noor-eyebrow">Met aandacht gekozen</span><strong><?=esc_html($t->name)?></strong><span class="noor-category-count"><?=$t->count?> <?=$t->count===1?'vondst':'vondsten'?> <b aria-hidden="true">↗</b></span></span></a><?php endforeach;?></div><?php return ob_get_clean();}
function stories(){ob_start();?><div class="noor-stories"><?php foreach(get_posts(['post_type'=>'noor_story','posts_per_page'=>3])as$p):?><article class="noor-story-card noor-reveal"><a href="<?=esc_url(get_permalink($p))?>"><?=get_the_post_thumbnail($p,'large')?></a><div><p class="noor-eyebrow"><?=esc_html(get_post_meta($p->ID,'noor_story_label',true)?:'Een beetje inspiratie')?></p><h3><a href="<?=esc_url(get_permalink($p))?>"><?=esc_html($p->post_title)?></a></h3><p><?=esc_html($p->post_excerpt)?></p><a class="noor-textlink" href="<?=esc_url(get_permalink($p))?>">Lees het verhaal ↗</a></div></article><?php endforeach;?></div><?php return ob_get_clean();}
function story(){ob_start();?><article class="noor-story-single"><header><p class="noor-eyebrow">Het atelierjournal</p><h1><?=esc_html(get_the_title())?></h1><p><?=esc_html(get_the_excerpt())?></p></header><?=get_the_post_thumbnail(null,'full')?><div class="noor-prose"><?=apply_filters('the_content',get_post_field('post_content',get_the_ID()))?><a class="noor-textlink" href="<?=link('inspiratie')?>">← Alle verhalen</a></div></article><?php return ob_get_clean();}
function catalog(){ob_start();echo '<div class="noor-shop-shell">';if(function_exists('woocommerce_content')){rewind_posts();woocommerce_breadcrumb();woocommerce_content();}else echo '<p>De winkel is tijdelijk niet beschikbaar.</p>';echo '</div>';return ob_get_clean();}
function footer(){ob_start();?><div class="noor-service-strip"><span>Met aandacht geselecteerd</span><span>Verzending binnen België</span><span>Veilig betalen via Mollie</span></div><div class="noor-footer"><div><a class="noor-logo" href="<?=link('')?>" aria-label="Atelier Noor — homepage"><?=logo()?></a><p><?=esc_html(field('noor_footer_text','Kleine dingen, een warm thuis. Ontdek onze collectie keramiek, textiel en woonaccessoires.'))?></p><p class="noor-demo-label">Demowinkel — geen echte verkoop of levering.</p></div><div><h2>Ontdek</h2><a href="<?=link('winkel')?>">De collectie</a><a href="<?=link('ons-verhaal')?>">Ons verhaal</a><a href="<?=link('inspiratie')?>">Inspiratie</a><a href="<?=link('contact')?>">Contact</a></div><div><h2>Goed om te weten</h2><a href="<?=link('verzenden-retourneren')?>">Verzenden & retourneren</a><a href="<?=link('veelgestelde-vragen')?>">Veelgestelde vragen</a><a href="<?=link('privacy')?>">Privacy</a><a href="<?=link('voorwaarden')?>">Voorwaarden</a></div><div><h2>Een vraag?</h2><p>We denken graag met je mee.</p><a href="mailto:<?=esc_attr(field('noor_email','info@mondaymakers.be'))?>"><?=esc_html(field('noor_email','info@mondaymakers.be'))?></a><p>Ma–vr · 10:00–17:00<br>Voorbeeldbereikbaarheid</p></div></div><div class="noor-footer-bottom"><span>© <?=date('Y')?> Atelier Noor · Een demo van Monday Makers</span><span>Bancontact · iDEAL · Kaart</span></div><?php return ob_get_clean();}
function contact(){ob_start();if(isset($_GET['ontvangen']))echo '<div class="noor-notice" role="status">Bedankt, je bericht is ontvangen. Je vindt deze testaanvraag terug in het beheer.</div>';?><form class="noor-form" method="post" action="<?=esc_url(admin_url('admin-post.php'))?>"><input type="hidden" name="action" value="noor_contact"><?php wp_nonce_field('noor_contact','noor_nonce');?><div class="noor-form-row"><label>Voornaam<input name="first_name" required maxlength="80" autocomplete="given-name"></label><label>Naam<input name="last_name" required maxlength="100" autocomplete="family-name"></label></div><label>E-mailadres<input type="email" name="email" required maxlength="200" autocomplete="email"></label><label>Waar kunnen we je mee helpen?<select name="topic"><option>Een productvraag</option><option>Verzending of retour</option><option>Een andere vraag</option></select></label><label>Je bericht<textarea name="message" rows="5" required maxlength="4000"></textarea></label><div class="noor-honey" aria-hidden="true"><label>Laat dit leeg<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="noor-consent"><input type="checkbox" name="consent" value="1" required> Ik ga akkoord met de <a href="<?=link('privacy')?>">privacyverklaring</a>.</label><button class="noor-button" type="submit">Verstuur je bericht ↗</button></form><?php return ob_get_clean();}
function submit(){if(!isset($_POST['noor_nonce'])||!is_scalar($_POST['noor_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['noor_nonce'])),'noor_contact'))wp_die('Ongeldige aanvraag.','',['response'=>403]);foreach(['first_name','last_name','email','message','topic','consent','website']as$k)if(isset($_POST[$k])&&!is_scalar($_POST[$k]))wp_die('Ongeldige invoer.','',['response'=>400]);$f=sanitize_text_field(wp_unslash($_POST['first_name']??''));$l=sanitize_text_field(wp_unslash($_POST['last_name']??''));$e=sanitize_email(wp_unslash($_POST['email']??''));$m=sanitize_textarea_field(wp_unslash($_POST['message']??''));if(!$f||!$l||!is_email($e)||!$m||empty($_POST['consent'])||!empty($_POST['website']))wp_die('Controleer de velden.','',['response'=>400]);$rate='noor_contact_'.hash_hmac('sha256',$_SERVER['REMOTE_ADDR']??'',wp_salt());if(get_transient($rate))wp_die('Wacht even voor je nog een bericht verzendt.','',['response'=>429]);set_transient($rate,1,60);$id=wp_insert_post(['post_type'=>'noor_inquiry','post_status'=>'private','post_title'=>mb_substr($f.' '.$l,0,180),'post_content'=>"Naam: $f $l\nE-mail: $e\nOnderwerp: ".sanitize_text_field(wp_unslash($_POST['topic']??''))."\n\n".mb_substr($m,0,4000)],true);if(is_wp_error($id))wp_die('Opslaan is niet gelukt. Probeer later opnieuw.','',['response'=>500]);wp_safe_redirect(add_query_arg('ontvangen','1',home_url('/contact/')));exit;}
add_action('admin_post_noor_contact',__NAMESPACE__.'\\submit');add_action('admin_post_nopriv_noor_contact',__NAMESPACE__.'\\submit');
add_action('init',function(){register_post_type('noor_story',['label'=>'Inspiratieverhalen','public'=>true,'show_in_rest'=>true,'menu_icon'=>'dashicons-art','supports'=>['title','editor','excerpt','thumbnail','revisions'],'rewrite'=>['slug'=>'journal']]);register_post_type('noor_inquiry',['label'=>'Winkelvragen','public'=>false,'show_ui'=>true,'supports'=>['title','editor'],'capability_type'=>'post','map_meta_cap'=>true]);wp_register_script('noor-editor',plugins_url('editor.js',__FILE__),['wp-blocks','wp-element','wp-server-side-render'],filemtime(__DIR__.'/editor.js'));foreach(['header','hero','products','categories','stories','story','footer','contact','search']as$name)register_block_type('noor/'.$name,['api_version'=>3,'editor_script'=>'noor-editor','render_callback'=>__NAMESPACE__.'\\'.($name==='search'?'search_form':$name)]);});
function search_form(){ob_start();?><form class="noor-product-search" role="search" action="<?=esc_url(home_url('/'))?>"><label for="noor-search">Wat zoek je voor je thuis?</label><div><input id="noor-search" type="search" name="s" placeholder="Bijvoorbeeld vaas of linnen" required><input type="hidden" name="post_type" value="product"><button type="submit">Zoeken ↗</button></div></form><?php return ob_get_clean();}
add_action('acf/init',function(){if(!function_exists('acf_add_options_page'))return;acf_add_options_page(['page_title'=>'Atelier Noor — winkelinhoud','menu_title'=>'Winkelinhoud','menu_slug'=>'noor-settings','capability'=>'manage_options','redirect'=>false,'icon_url'=>'dashicons-store']);acf_add_local_field_group(['key'=>'group_noor_settings','title'=>'Winkelpresentatie','location'=>[[['param'=>'options_page','operator'=>'==','value'=>'noor-settings']]],'fields'=>[['key'=>'field_noor_hero_slides','name'=>'noor_hero_slides','label'=>'Uitgelichte collectie op de homepage','type'=>'repeater','min'=>1,'max'=>3,'layout'=>'block','sub_fields'=>[['key'=>'field_noor_slide_image','name'=>'image','label'=>'Sfeerfoto','type'=>'image','return_format'=>'id','required'=>1],['key'=>'field_noor_slide_label','name'=>'label','label'=>'Kleine boventitel','type'=>'text'],['key'=>'field_noor_slide_title','name'=>'title','label'=>'Titel','type'=>'text','required'=>1],['key'=>'field_noor_slide_button','name'=>'button','label'=>'Linktekst','type'=>'text'],['key'=>'field_noor_slide_product','name'=>'product','label'=>'Gekoppeld WooCommerce-product','type'=>'post_object','post_type'=>['product'],'return_format'=>'id']]],['key'=>'field_noor_footer_text','name'=>'noor_footer_text','label'=>'Korte winkelomschrijving in footer','type'=>'textarea'],['key'=>'field_noor_email','name'=>'noor_email','label'=>'Contactadres','type'=>'email']]]);acf_add_local_field_group(['key'=>'group_noor_product','title'=>'Materiaal & verzorging','location'=>[[['param'=>'post_type','operator'=>'==','value'=>'product']]],'fields'=>[['key'=>'field_noor_material','name'=>'noor_material','label'=>'Materiaal','type'=>'text'],['key'=>'field_noor_care','name'=>'noor_care','label'=>'Onderhoudsadvies','type'=>'textarea']]]);acf_add_local_field_group(['key'=>'group_noor_story','title'=>'Verhaal','location'=>[[['param'=>'post_type','operator'=>'==','value'=>'noor_story']]],'fields'=>[['key'=>'field_noor_story_label','name'=>'noor_story_label','label'=>'Kleine boventitel','type'=>'text']]]);});
add_filter('woocommerce_product_tabs',function($tabs){if(get_post_meta(get_the_ID(),'noor_material',true)||get_post_meta(get_the_ID(),'noor_care',true))$tabs['noor_care']=['title'=>'Materiaal & verzorging','priority'=>25,'callback'=>function(){echo '<h2>Mooi houden, lang genieten</h2><p>'.esc_html(get_post_meta(get_the_ID(),'noor_material',true)).'</p><p>'.nl2br(esc_html(get_post_meta(get_the_ID(),'noor_care',true))).'</p>';}];return$tabs;});
// Demonstratiewinkel: nooit live-betaalsleutels of een ander echt betaalpad gebruiken.
add_filter('pre_option_mollie-payments-for-woocommerce_test_mode_enabled',fn()=>'yes');
add_filter('pre_option_mollie-payments-for-woocommerce_live_api_key',fn()=>'');
add_filter('woocommerce_available_payment_gateways',function($gateways){if(is_admin()&&!wp_doing_ajax())return$gateways;foreach($gateways as$id=>$g)if(strpos($id,'mollie_wc_gateway_')!==0)unset($gateways[$id]);return$gateways;});
add_action('woocommerce_before_checkout_form',function(){wc_print_notice('Dit is een demowinkel. Alleen Mollie-testbetalingen zijn mogelijk; er wordt niets geleverd. Gebruik uitsluitend testgegevens.','notice');if(!get_option('mollie-payments-for-woocommerce_test_api_key'))wc_print_notice('De Mollie-testsleutel is nog niet gekoppeld. Je kunt de winkelmand en checkout bekijken; betalen is beschikbaar na het koppelen.','notice');});
add_filter('woocommerce_checkout_privacy_policy_text',fn()=>'We verwerken je testgegevens voor deze demo-bestelling. Lees onze [privacy_policy].');
add_action('admin_notices',function(){if(!current_user_can('manage_woocommerce'))return;echo '<div class="notice notice-info"><p><strong>Atelier Noor is een demowinkel.</strong> Mollie staat verplicht in testmodus. Beheer producten en orders in WooCommerce; de homepagebeelden staan onder Winkelinhoud.</p></div>';});

add_filter('woocommerce_add_to_cart_fragments',function($fragments){$fragments['.noor-cart-count']='<span class="noor-cart-count">'.(WC()->cart?WC()->cart->get_cart_contents_count():0).'</span>';return$fragments;});
